     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    43	            throw new HotelException(
    44	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    45	        }
    46	
    47	        validateRatePlan(request);
    48	
    49	        Price price = priceCalculator.calculate(
    50	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    51	        return store.add(request, price);
    52	    }
    53	
    54	    private void validateRatePlan(NewReservation request) {
    55	        switch (request.ratePlan()) {
    56	            case CORPORATE -> {
    57	                if (request.companyCode() == null
    58	                        || !PriceCalculator.CORPORATE_DISCOUNTS.containsKey(request.companyCode())) {
    59	                    throw new HotelException(
    60	                            ErrorCode.INVALID_REQUEST,
    61	                            "CORPORATE rate plan requires a valid company code");
    62	                }
    63	            }
    64	            case WEEKEND_PACKAGE -> {
    65	                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
    66	                if (nights != 2) {
    67	                    throw new HotelException(
    68	                            ErrorCode.INVALID_REQUEST,
    69	                            "WEEKEND_PACKAGE requires exactly 2 nights");
    70	                }
    71	                if (request.checkIn().getDayOfWeek() != java.time.DayOfWeek.FRIDAY
    72	                        || request.checkOut().getDayOfWeek() != java.time.DayOfWeek.SUNDAY) {
    73	                    throw new HotelException(
    74	                            ErrorCode.INVALID_REQUEST,
    75	                            "WEEKEND_PACKAGE requires check-in on Friday and check-out on Sunday");
    76	                }
    77	            }
    78	            case LONG_STAY -> {
    79	                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
    80	                if (nights < 7) {
    81	                    throw new HotelException(
    82	                            ErrorCode.INVALID_REQUEST, "LONG_STAY requires at least 7 nights");
    83	                }
    84	            }
    85	            default -> {
    86	                // No additional validation needed for STANDARD and NON_REFUNDABLE
    87	            }
    88	        }
    89	    }
    90	
    91	    public Reservation find(long reservationId) {
    92	        return store.find(reservationId)
    93	                .orElseThrow(() -> new HotelException(
    94	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    95	    }
    96	
    97	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    98	    public synchronized Reservation confirm(long reservationId) {
    99	        Reservation reservation = find(reservationId);
   100	        if (reservation.status() != ReservationStatus.PENDING) {
   101	            throw notAllowed(reservation, "confirm");
   102	        }
   103	        reservation.confirmPayment();
   104	        store.update(reservation);
   105	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
   106	        emailSender.send(
   107	                reservation.guest().email(),
   108	                "Reserva confirmada - " + HOTEL_NAME,
   109	                confirmationEmailBody(reservation, receipt));
   110	        return reservation;
   111	    }
   112	
   113	    /**
   114	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   115	     * reservation was never paid, so nothing comes back).
   116	     */
   117	    public synchronized Reservation cancel(long reservationId) {
   118	        Reservation reservation = find(reservationId);
   119	        if (reservation.status() != ReservationStatus.PENDING
   120	                && reservation.status() != ReservationStatus.CONFIRMED) {
   121	            throw notAllowed(reservation, "cancel");
   122	        }
   123	        BigDecimal refund = switch (reservation.ratePlan()) {
   124	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
   125	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   126	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(new BigDecimal("2")));
   127	        };
   128	        reservation.cancel(refund);
   129	        store.update(reservation);
   130	        return reservation;
   131	    }
   132	
   133	    public synchronized Reservation checkIn(long reservationId) {
   134	        Reservation reservation = find(reservationId);
   135	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   136	            throw notAllowed(reservation, "check in");
   137	        }
   138	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   139	        store.update(reservation);
   140	        return reservation;
   141	    }
   142	
   143	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   144	    public synchronized ReservationReceipt checkOut(long reservationId) {
   145	        Reservation reservation = find(reservationId);
   146	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   147	            throw notAllowed(reservation, "check out");
   148	        }
   149	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   150	        store.update(reservation);
   151	        return new ReservationReceipt(reservation, roomOf(reservation));
   152	    }
   153	
   154	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   155	    public ReservationReceipt receiptCopy(long reservationId) {
   156	        Reservation reservation = find(reservationId);
   157	        if (!reservation.isPaid()) {
   158	            throw notAllowed(reservation, "issue a receipt for");
   159	        }
   160	        return new ReservationReceipt(reservation, roomOf(reservation));
   161	    }
   162	
   163	    private Room roomOf(Reservation reservation) {
   164	        return rooms.find(reservation.roomNumber()).orElseThrow();
   165	    }
   166	
   167	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   168	        return "Olá, " + reservation.guest().name() + "!\n\n"
   169	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   170	                + receipt.text() + "\n"
   171	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   172	                + "Até breve!\n";
   173	    }
   174	
   175	    private static HotelException notAllowed(Reservation reservation, String operation) {
   176	        return new HotelException(
   177	                ErrorCode.OPERATION_NOT_ALLOWED,
   178	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   179	    }
   180	}
     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import hotel.rooms.RoomType;
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.time.DayOfWeek;
     8	import java.time.LocalDate;
     9	import java.time.Month;
    10	import java.util.Map;
    11	
    12	/**
    13	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    14	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    15	 * (half-even) at every step.
    16	 */
    17	public final class PriceCalculator {
    18	
    19	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    20	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    21	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
    22	
    23	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
    24	            "TECNOSUL", new BigDecimal("0.12"),
    25	            "AGROVALE", new BigDecimal("0.18"),
    26	            "FARMAVIDA", new BigDecimal("0.25"));
    27	
    28	    static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
    29	            RoomType.STANDARD, new BigDecimal("520.00"),
    30	            RoomType.DELUXE, new BigDecimal("820.00"),
    31	            RoomType.SUITE, new BigDecimal("1200.00"));
    32	
    33	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    34	        int nights = 0;
    35	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    36	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    37	            subtotal = subtotal.add(nightPrice(room, night));
    38	            nights++;
    39	        }
    40	
    41	        BigDecimal discount;
    42	        BigDecimal total;
    43	
    44	        if (ratePlan == RatePlan.WEEKEND_PACKAGE) {
    45	            BigDecimal packagePrice = WEEKEND_PACKAGE_PRICES.get(room.type());
    46	            total = packagePrice;
    47	            discount = cents(subtotal.subtract(packagePrice));
    48	        } else {
    49	            discount = switch (ratePlan) {
    50	                case STANDARD -> cents(BigDecimal.ZERO);
    51	                case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    52	                case CORPORATE -> {
    53	                    BigDecimal discountRate = CORPORATE_DISCOUNTS.get(companyCode);
    54	                    yield cents(subtotal.multiply(discountRate));
    55	                }
    56	                case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
    57	                default -> cents(BigDecimal.ZERO);
    58	            };
    59	            total = subtotal.subtract(discount);
    60	        }
    61	
    62	        return new Price(nights, subtotal, discount, total);
    63	    }
    64	
    65	    BigDecimal nightPrice(Room room, LocalDate night) {
    66	        BigDecimal nightlyRate = room.nightlyRate();
    67	        if (isHighSeason(night)) {
    68	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    69	        }
    70	        return cents(nightlyRate);
    71	    }
    72	
    73	    /** High season: from December 15 to the end of February, and the whole of July. */
    74	    static boolean isHighSeason(LocalDate date) {
    75	        Month month = date.getMonth();
    76	        return month == Month.JANUARY
    77	                || month == Month.FEBRUARY
    78	                || month == Month.JULY
    79	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    80	    }
    81	
    82	    static BigDecimal cents(BigDecimal value) {
    83	        return value.setScale(2, RoundingMode.HALF_EVEN);
    84	    }
    85	}
