     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    43	            throw new HotelException(
    44	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    45	        }
    46	
    47	        validateRatePlan(request);
    48	
    49	        Price price = priceCalculator.calculate(
    50	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    51	        return store.add(request, price);
    52	    }
    53	
    54	    private void validateRatePlan(NewReservation request) {
    55	        switch (request.ratePlan()) {
    56	            case CORPORATE -> {
    57	                if (request.companyCode() == null
    58	                        || !PriceCalculator.CORPORATE_DISCOUNTS.containsKey(request.companyCode())) {
    59	                    throw new HotelException(
    60	                            ErrorCode.INVALID_REQUEST,
    61	                            "CORPORATE rate plan requires a valid company code");
    62	                }
    63	            }
    64	            case WEEKEND_PACKAGE -> {
    65	                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
    66	                if (nights != 2) {
    67	                    throw new HotelException(
    68	                            ErrorCode.INVALID_REQUEST,
    69	                            "WEEKEND_PACKAGE requires exactly 2 nights");
    70	                }
    71	                if (request.checkIn().getDayOfWeek() != java.time.DayOfWeek.FRIDAY
    72	                        || request.checkOut().getDayOfWeek() != java.time.DayOfWeek.SUNDAY) {
    73	                    throw new HotelException(
    74	                            ErrorCode.INVALID_REQUEST,
    75	                            "WEEKEND_PACKAGE requires check-in on Friday and check-out on Sunday");
    76	                }
    77	            }
    78	            case LONG_STAY -> {
    79	                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
    80	                if (nights < 7) {
    81	                    throw new HotelException(
    82	                            ErrorCode.INVALID_REQUEST, "LONG_STAY requires at least 7 nights");
    83	                }
    84	            }
    85	            default -> {
    86	                // No additional validation needed for STANDARD and NON_REFUNDABLE
    87	            }
    88	        }
    89	    }
