    91	    public Reservation find(long reservationId) {
    92	        return store.find(reservationId)
    93	                .orElseThrow(() -> new HotelException(
    94	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    95	    }
    96	
    97	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    98	    public synchronized Reservation confirm(long reservationId) {
    99	        Reservation reservation = find(reservationId);
   100	        if (reservation.status() != ReservationStatus.PENDING) {
   101	            throw notAllowed(reservation, "confirm");
   102	        }
   103	        reservation.confirmPayment();
   104	        store.update(reservation);
   105	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
   106	        emailSender.send(
   107	                reservation.guest().email(),
   108	                "Reserva confirmada - " + HOTEL_NAME,
   109	                confirmationEmailBody(reservation, receipt));
   110	        return reservation;
   111	    }
   112	
   113	    /**
   114	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   115	     * reservation was never paid, so nothing comes back).
   116	     */
   117	    public synchronized Reservation cancel(long reservationId) {
   118	        Reservation reservation = find(reservationId);
   119	        if (reservation.status() != ReservationStatus.PENDING
   120	                && reservation.status() != ReservationStatus.CONFIRMED) {
   121	            throw notAllowed(reservation, "cancel");
   122	        }
   123	        BigDecimal refund = switch (reservation.ratePlan()) {
   124	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
   125	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   126	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(new BigDecimal("2")));
   127	        };
   128	        reservation.cancel(refund);
   129	        store.update(reservation);
   130	        return reservation;
   131	    }
   132	
   133	    public synchronized Reservation checkIn(long reservationId) {
   134	        Reservation reservation = find(reservationId);
   135	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   136	            throw notAllowed(reservation, "check in");
   137	        }
   138	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   139	        store.update(reservation);
   140	        return reservation;
   141	    }
   142	
   143	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   144	    public synchronized ReservationReceipt checkOut(long reservationId) {
   145	        Reservation reservation = find(reservationId);
   146	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   147	            throw notAllowed(reservation, "check out");
   148	        }
   149	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   150	        store.update(reservation);
   151	        return new ReservationReceipt(reservation, roomOf(reservation));
   152	    }
   153	
   154	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   155	    public ReservationReceipt receiptCopy(long reservationId) {
   156	        Reservation reservation = find(reservationId);
   157	        if (!reservation.isPaid()) {
   158	            throw notAllowed(reservation, "issue a receipt for");
   159	        }
   160	        return new ReservationReceipt(reservation, roomOf(reservation));
   161	    }
   162	
   163	    private Room roomOf(Reservation reservation) {
   164	        return rooms.find(reservation.roomNumber()).orElseThrow();
   165	    }
